/* ---------- 요청 진입점 ---------- */
function onMessage(c, text) {
  let r; try { r = JSON.parse(text); } catch (e) { return; }
  if (!r || typeof r.op !== 'string') return;
  const fn = H[r.op];
  const reply = o => { if (r.q != null) c.send(Object.assign({ q: r.q }, o)); };
  if (!fn || (!['signup', 'login', 'resume', 'ping'].includes(r.op) && !c.user)) return reply({ err: '로그인이 필요해요', auth: true });
  try { reply(Object.assign({ ok: true }, fn(c, r))); }
  catch (e) { if (e instanceof Fail) reply({ err: e.message }); else { console.error(r.op, e); reply({ err: '서버에서 문제가 생겼어요' }); } }
}


/* ---------- 바이브톡(통화): 서버는 연결 신호만 중계하고, 소리·영상은 두 기기가 직접 주고받습니다 ---------- */
const calls = new Map();
const callOf = uid => { for (const c of calls.values()) if (c.from === uid || c.to === uid) return c; return null; };
function logCall(from, to, kind, text, dur) {
  const rid = dmId(from, to);
  let room = db.rooms[rid];
  if (!room) { room = mkRoom({ id: rid, type: 'dm' }); addMember(room, from); addMember(room, to); }
  for (const x of [from, to]) if (!room.members[x]) addMember(room, x);
  addMsg(room, { from, t: 'call', text: (kind === 'video' ? '바이브톡 영상 ' : '바이브톡 ') + text, img: '', dur: dur || 0, nm: '' });
  pushSync(from); pushSync(to);
}
function endCall(id, reason) {
  const call = calls.get(id); if (!call) return;
  clearTimeout(call.timer); calls.delete(id);
  send(call.from, { ev: 'call_end', callId: id, reason }); send(call.to, { ev: 'call_end', callId: id, reason });
  const dur = call.t0 ? Math.max(0, Math.round((now() - call.t0) / 1000)) : 0;
  const mm = String(Math.floor(dur / 60)).padStart(2, '0') + ':' + String(dur % 60).padStart(2, '0');
  const label = call.t0 ? mm : ({ declined: '거절됨', canceled: '취소됨', missed: '부재중', busy: '통화 중' }[reason] || '종료');
  logCall(call.from, call.to, call.kind, label, dur);
}
H.call = (c, r) => {
  const u = U(c); const to = db.users[r.to];
  need(to && u.friends.includes(to.id), '친구에게만 바이브톡을 걸 수 있어요');
  need(!callOf(u.id), '이미 통화 중이에요');
  const kind = r.kind === 'video' ? 'video' : 'voice';
  need(online(to.id), '상대가 지금 접속 중이 아니에요');
  if (callOf(to.id)) { logCall(u.id, to.id, kind, '통화 중', 0); throw new Fail('상대가 다른 통화 중이에요'); }
  const id = rnd(8);
  const call = { id, from: u.id, to: to.id, kind, state: 'ringing', t0: 0, timer: setTimeout(() => endCall(id, 'missed'), 45000) };
  calls.set(id, call);
  send(to.id, { ev: 'call_in', callId: id, kind, from: Object.assign({ id: u.id }, publicProf(u, viewIdx(u, to.id))) });
  return { callId: id };
};
H.call_answer = (c, r) => {
  const u = U(c); const call = calls.get(r.callId);
  need(call && call.to === u.id && call.state === 'ringing', '이미 끝난 통화예요');
  if (!r.accept) { endCall(call.id, 'declined'); return {}; }
  call.state = 'active'; call.t0 = now(); clearTimeout(call.timer);
  send(call.from, { ev: 'call_accepted', callId: call.id });
  const s = conns.get(u.id); if (s) for (const x of s) if (x !== c) x.send({ ev: 'call_end', callId: call.id, reason: 'elsewhere', silent: true });
  return {};
};
H.sig = (c, r) => {
  const u = U(c); const call = calls.get(r.callId);
  need(call && (call.from === u.id || call.to === u.id), '통화를 찾을 수 없어요');
  send(call.from === u.id ? call.to : call.from, { ev: 'call_sig', callId: call.id, data: r.data });
  return {};
};
H.call_end = (c, r) => {
  const u = U(c); const call = calls.get(r.callId); if (!call || (call.from !== u.id && call.to !== u.id)) return {};
  endCall(call.id, call.state === 'ringing' ? (call.from === u.id ? 'canceled' : 'declined') : 'ended'); return {};
};

/* ---------- HTTP ---------- */
const MIME = { jpg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif' };
const server = http.createServer((req, res) => {
  const url = (req.url || '/').split('?')[0];
  const hdr = (type, extra) => Object.assign({ 'content-type': type, 'x-content-type-options': 'nosniff' }, extra || {});
  if (url === '/' || url === '/index.html') { res.writeHead(200, hdr('text/html; charset=utf-8', { 'cache-control': 'no-cache' })); return res.end(ASSETS.html); }
  if (url === '/manifest.webmanifest') {
    res.writeHead(200, hdr('application/manifest+json'));
    return res.end(JSON.stringify({ name: '바이브', short_name: '바이브', start_url: '/', display: 'standalone', background_color: '#000000', theme_color: '#000000', lang: 'ko',
      icons: [{ src: '/icon-192.png', sizes: '192x192', type: 'image/png' }, { src: '/icon-512.png', sizes: '512x512', type: 'image/png' }] }));
  }
  if (url === '/icon-192.png' || url === '/favicon.ico' || url === '/apple-touch-icon.png') { res.writeHead(200, hdr('image/png', { 'cache-control': 'public,max-age=86400' })); return res.end(ASSETS.icon192); }
  if (url === '/icon-512.png') { res.writeHead(200, hdr('image/png', { 'cache-control': 'public,max-age=86400' })); return res.end(ASSETS.icon512); }
  if (url === '/sw.js') { res.writeHead(200, hdr('text/javascript')); return res.end("self.addEventListener('install',e=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',()=>{});"); }
  if (url === '/health') { res.writeHead(200, hdr('text/plain')); return res.end('ok'); }
  const m = /^\/m\/([a-f0-9]{24})\.(jpg|png|webp|gif)$/.exec(url);
  if (m) {
    const f = path.join(MEDIA_DIR, m[1] + '.' + m[2]);
    return fs.readFile(f, (err, buf) => {
      if (err) { res.writeHead(404); return res.end(); }
      res.writeHead(200, hdr(MIME[m[2]], { 'cache-control': 'public,max-age=31536000,immutable' })); res.end(buf);
    });
  }
  res.writeHead(404, hdr('text/plain')); res.end('not found');
});
server.on('upgrade', (req, sock) => {
  if ((req.url || '').split('?')[0] !== '/ws' || String(req.headers.upgrade).toLowerCase() !== 'websocket') return sock.destroy();
  const key = req.headers['sec-websocket-key']; if (!key) return sock.destroy();
  const acc = crypto.createHash('sha1').update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
  sock.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ' + acc + '\r\n\r\n');
  sock.setNoDelay(true); new Conn(sock);
});
server.listen(PORT, () => {
  console.log('\n  바이브 서버가 켜졌어요!');
  console.log('  이 컴퓨터에서 열기:  http://localhost:' + PORT);
  console.log('  데이터 저장 위치:    ' + DATA_DIR + '\n');
});

